from Crypto.Util.number import *
from secret import flag

assert len(flag) == 36

p = getPrime(512)
q = getPrime(512)
n = p * q
e = 65537

sum = 0
for idx, chr in enumerate(flag):
    for _ in range(chr): sum += pow(idx + bytes_to_long(b'RSA_is_easy_but_if_I_add_others_.....'),e,n)

print(f"n = {n}")
print(f"e = {e}")
print(f"sum = {sum}")

